package cache

import (
	"chatapp/backend/config"
	"chatapp/backend/log"
	"context"
	"fmt"
	"strconv"
	"strings"
	"sync/atomic"
	"time"

	redis "github.com/redis/go-redis/v9"
)

var (
	redisClient *redis.Client
	enabledFlag int32
)

func IsEnabled() bool {
	return atomic.LoadInt32(&enabledFlag) == 1
}

func Init() {
	cfg := config.GetConfig()
	if !cfg.RedisEnabled {
		log.Logger.Info("redis disabled by config")
		return
	}

	redisClient = redis.NewClient(&redis.Options{
		Addr:         cfg.RedisAddr,
		Password:     cfg.RedisPassword,
		DB:           cfg.RedisDB,
		ReadTimeout:  2 * time.Second,
		WriteTimeout: 2 * time.Second,
		DialTimeout:  2 * time.Second,
	})

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	if err := redisClient.Ping(ctx).Err(); err != nil {
		log.Logger.Warn("redis ping failed, fallback to no-redis mode", log.Any("error", err))
		redisClient = nil
		atomic.StoreInt32(&enabledFlag, 0)
		return
	}

	atomic.StoreInt32(&enabledFlag, 1)
	log.Logger.Info("redis init success", log.String("addr", cfg.RedisAddr), log.Int("db", cfg.RedisDB))
}

func Close() error {
	if redisClient == nil {
		return nil
	}
	err := redisClient.Close()
	redisClient = nil
	atomic.StoreInt32(&enabledFlag, 0)
	return err
}

func key(parts ...string) string {
	prefix := config.GetConfig().RedisKeyPrefix
	if prefix == "" {
		prefix = "chatapp:"
	}
	return prefix + strings.Join(parts, ":")
}

func onlineTTL() time.Duration {
	ttlSeconds := config.GetConfig().RedisOnlineTTLSeconds
	if ttlSeconds <= 0 {
		ttlSeconds = 90
	}
	return time.Duration(ttlSeconds) * time.Second
}

func loginWindow() time.Duration {
	seconds := config.GetConfig().RedisLoginWindowSeconds
	if seconds <= 0 {
		seconds = 60
	}
	return time.Duration(seconds) * time.Second
}

func loginMaxAttempts() int64 {
	maxAttempts := config.GetConfig().RedisLoginMaxAttempts
	if maxAttempts <= 0 {
		maxAttempts = 8
	}
	return int64(maxAttempts)
}

func MarkUserOnline(userUUID string) error {
	if !IsEnabled() || strings.TrimSpace(userUUID) == "" {
		return nil
	}

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	return redisClient.Set(ctx, key("online", userUUID), strconv.FormatInt(time.Now().Unix(), 10), onlineTTL()).Err()
}

func RefreshUserOnline(userUUID string) error {
	return MarkUserOnline(userUUID)
}

func MarkUserOffline(userUUID string) error {
	if !IsEnabled() || strings.TrimSpace(userUUID) == "" {
		return nil
	}

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	return redisClient.Del(ctx, key("online", userUUID)).Err()
}

func IsUserOnline(userUUID string) (bool, error) {
	if !IsEnabled() || strings.TrimSpace(userUUID) == "" {
		return false, nil
	}

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	exists, err := redisClient.Exists(ctx, key("online", userUUID)).Result()
	if err != nil {
		return false, err
	}
	return exists > 0, nil
}

func CheckLoginRateLimit(ip, username string) (bool, int64, error) {
	if !IsEnabled() {
		return true, 0, nil
	}

	ip = strings.TrimSpace(ip)
	if ip == "" {
		ip = "unknown"
	}
	username = strings.TrimSpace(username)
	if username == "" {
		username = "_"
	}

	loginKey := key("login_limit", ip, username)
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	count, err := redisClient.Incr(ctx, loginKey).Result()
	if err != nil {
		return true, 0, err
	}
	if count == 1 {
		if err = redisClient.Expire(ctx, loginKey, loginWindow()).Err(); err != nil {
			return true, count, err
		}
	}
	return count <= loginMaxAttempts(), count, nil
}

func ResetLoginRateLimit(ip, username string) error {
	if !IsEnabled() {
		return nil
	}

	ip = strings.TrimSpace(ip)
	if ip == "" {
		ip = "unknown"
	}
	username = strings.TrimSpace(username)
	if username == "" {
		username = "_"
	}

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	_, err := redisClient.Del(ctx, key("login_limit", ip, username)).Result()
	return err
}

func BuildLoginRateLimitMessage(currentCount int64) string {
	maxAttempts := loginMaxAttempts()
	windowSeconds := int64(loginWindow().Seconds())
	return fmt.Sprintf("登录过于频繁（%d/%d），请在 %d 秒后重试", currentCount, maxAttempts, windowSeconds)
}

